import{_ as n,c as o,o as a,ah as i}from"./chunks/framework.D0LKgEKT.js";const h=JSON.parse(`{"title":"Nvidia's development voice and development environment","description":"","frontmatter":{},"headers":[],"relativePath":"NVIDIA.md","filePath":"NVIDIA.md","lastUpdated":1762773706000}`),t={name:"NVIDIA.md"};function r(l,e,d,p,s,m){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="nvidia-s-development-voice-and-development-environment" tabindex="-1">Nvidia&#39;s development voice and development environment <a class="header-anchor" href="#nvidia-s-development-voice-and-development-environment" aria-label="Permalink to “Nvidia&#39;s development voice and development environment”">​</a></h1><p>&#39;&#39;&#39;md</p><h2 id="core-development-language" tabindex="-1">Core development language <a class="header-anchor" href="#core-development-language" aria-label="Permalink to “Core development language”">​</a></h2><ol><li><p>C/C++ : The most core and fundamental programming language. It is used for writing high-performance CUDA core functions and is the preferred choice for drivers, high-performance computing, and low-level optimization.</p></li><li><p>Python: The most popular language in the fields of AI and deep learning. Calling CUDA through mainstream frameworks such as PyTorch and TensorFlow is the main force for model training and experimentation.</p></li><li><p>Fortran: Mainly used in scientific computing and high-performance computing fields, NVIDIA provides a dedicated CUDA Fortran compiler.</p></li></ol><h2 id="core-development-environment-and-tools" tabindex="-1">Core development environment and tools <a class="header-anchor" href="#core-development-environment-and-tools" aria-label="Permalink to “Core development environment and tools”">​</a></h2><ol><li><p>CUDA Toolkit: The most fundamental and indispensable software development kit. It includes a compiler (NVCC), debugger, performance analyzer and GPU acceleration library.</p></li><li><p>Integrated Development Environment (IDE)</p></li></ol><p>:Visual Studio + NVIDIA Nsight: The main development environment on Windows.</p><p>:VS Code + related plugins: A lightweight and cross-platform popular choice.</p><p>:Nsight Eclipse Edition: The official IDE on Linux.</p><ol start="3"><li>Domain-specific SDK</li></ol><p>:NVIDIA HPC SDK: Provides a complete set of compilers and tools for high-performance computing applications.</p><p>:JetPack SDK: Provides a complete development environment for Jetson edge computing devices.</p><p>:TensorRT: An SDK for high-performance deep learning inference.</p><p>In summary, NVIDIA&#39;s development mainly focuses on C/C++ and Python. On the CUDA foundation platform, it uses tools such as Nsight for development and debugging, and selects corresponding SDKS based on different fields (HPC, AI, edge). &#39;&#39;&#39;</p><p>Learn more about the <a href="https://www.nvidia.com/zh-tw/technologies/cuda-x/" target="_blank" rel="noreferrer">CUDA</a></p>',15)])])}const v=n(t,[["render",r]]);export{h as __pageData,v as default};
